    74	        if (order != null) {
    75	            this.status = BidStatus.MATCHED;
    76	
    77	            // Order 쪽에도 관계 설정
    78	            if (order.getOrderBid() != this) {
    79	                order.assignOrderBid(this);
    80	            }
    81	        }
    82	    }
    83	
    84	    /**
    85	     * Sale과의 양방향 관계를 설정합니다.
    86	     *
    87	     * @param sale 연결할 Sale 객체
    88	     */
    89	    public void assignSale(Sale sale) {
    90	        this.sale = sale;
    91	        this.status = BidStatus.MATCHED;
    92	    }
    93	
    94	    /**
    95	     * 즉시 구매로 표시합니다.
    96	     */
    97	    public void markAsInstantPurchase() {
    98	        this.isInstantPurchase = true;
    99	    }
   100	
   101	    /**
   102	     * 입찰 상태를 업데이트합니다.
   103	     *
   104	     * @param newStatus 새 입찰 상태
   105	     */
   106	    public void updateStatus(BidStatus newStatus) {
   107	        this.status = newStatus;
   108	    }
   109	}

